import json,html,os
SITE="RoadMed Hub";BASE="https://blackbucket548.github.io/roadmed-hub";PREFIX="/roadmed-hub"
CATS={"housing":"Housing & Short-Term Stays","mileage":"Mileage & Expense Tracking","apparel":"Scrubs, Apparel & Gear","ce":"CE Credits, Licensing & Credentialing","scheduling":"Scheduling & Route Planning","staffing":"Staffing Agencies (Nurses)","crm":"CRM & Sales Tools (Reps)","finance":"Finance & Taxes for 1099 Travelers","wellness":"Wellness"}
AUD={"nurses":"Travel Nurses","reps":"Device Sales Reps"}
L=[dict(name=n,url=u,cat=c,desc=d,aud=a.split(",")) for n,u,c,d,a in json.load(open("listings.json"))]
e=html.escape
CSS="""*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#0f172a;background:#f8fafc;line-height:1.5}a{color:#0d9488}header{background:#0f766e;color:#fff}header .w{display:flex;gap:16px;align-items:center;flex-wrap:wrap;padding:14px 20px}header a{color:#fff;text-decoration:none;font-weight:600}.logo{font-size:1.3rem;margin-right:auto}.w{max-width:1100px;margin:0 auto;padding:20px}.hero{background:linear-gradient(135deg,#0f766e,#0369a1);color:#fff}.hero h1{font-size:clamp(1.7rem,4vw,2.6rem);margin:.2em 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:16px}.card h3{margin:0 0 4px}.tag{display:inline-block;font-size:.75rem;background:#e0f2fe;color:#075985;border-radius:99px;padding:2px 8px;margin:2px 4px 0 0}.tag.c{background:#ccfbf1;color:#115e59}.feat{border:2px dashed #f59e0b;background:#fffbeb;text-align:center}.ctl{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}input,select{padding:10px;border:1px solid #cbd5e1;border-radius:8px;font-size:1rem;flex:1;min-width:150px}.btn{display:inline-block;background:#f59e0b;color:#111;padding:10px 16px;border-radius:8px;border:0;font-weight:700;text-decoration:none;cursor:not-allowed}.note{font-size:.85rem;color:#b45309;font-weight:600}footer{color:#64748b;font-size:.85rem;text-align:center;padding:30px}.cats a{display:inline-block;margin:4px 6px 4px 0;padding:6px 10px;background:#fff;border:1px solid #e2e8f0;border-radius:8px;text-decoration:none}"""
def page(path,title,desc,body):
  url=BASE+"/"+path.replace("index.html","")
  h=f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><link rel="stylesheet" href="/style.css"></head><body><header><div class="w" style="max-width:1100px;margin:0 auto"><a class="logo" href="/">🩺 {SITE}</a><a href="/#directory">Directory</a><a href="/sponsor/">Sponsor us</a><a href="/#newsletter">Newsletter</a></div></header>{body}<footer>{SITE} is operated by SA Lab Services LLC. Independent directory. Listings are not endorsements; no paid placements yet. Verify details with each provider.</footer></body></html>"""
  h=h.replace('href="/','href="'+PREFIX+'/')
  os.makedirs(os.path.dirname("dist/"+path) or "dist",exist_ok=True);open("dist/"+path,"w").write(h)
def card(x):
  t="".join(f'<span class="tag">{AUD[a]}</span>' for a in x["aud"])
  return f'<div class="card" data-cat="{x["cat"]}" data-aud="{" ".join(x["aud"])}" data-q="{e((x["name"]+" "+x["desc"]).lower())}"><h3><a href="{x["url"]}" rel="nofollow noopener" target="_blank">{e(x["name"])}</a></h3><p>{e(x["desc"])}</p><a class="tag c" href="/category/{x["cat"]}/">{CATS[x["cat"]]}</a>{t}</div>'
FEAT='<div class="card feat"><h3>⭐ Featured spot available</h3><p>Pinned placement + newsletter mention.</p><a href="/sponsor/">Learn about sponsoring →</a></div>'
NEWS='<section id="newsletter" class="w"><div class="card"><h2>Newsletter</h2><p>New tools, housing deals, and road tips for travel nurses and med device reps. Free, about once a week, unsubscribe anytime.</p><form action="https://buttondown.com/api/emails/embed-subscribe/blackbucket" method="post" target="_blank" class="ctl"><input type="email" name="email" required placeholder="you@example.com" aria-label="Email"><input type="hidden" name="tag" value="roadmed-hub"><button class="btn" style="cursor:pointer" type="submit">Subscribe</button></form></div></section>'
catlinks='<div class="cats">'+"".join(f'<a href="/category/{k}/">{v}</a>' for k,v in CATS.items())+"</div>"
os.makedirs("dist",exist_ok=True);open("dist/style.css","w").write(CSS)
opts="".join(f'<option value="{k}">{v}</option>' for k,v in CATS.items())
JS="""<script>const q=document.getElementById('q'),a=document.getElementById('aud'),c=document.getElementById('cat'),n=document.getElementById('n');function f(){let k=0;document.querySelectorAll('#list .card').forEach(el=>{const ok=(!q.value||el.dataset.q.includes(q.value.toLowerCase()))&&(!a.value||el.dataset.aud.includes(a.value))&&(!c.value||el.dataset.cat==c.value);el.style.display=ok?'':'none';if(ok)k++});n.textContent=k+' listings'}[q,a,c].forEach(x=>x.addEventListener('input',f));const p=new URLSearchParams(location.search);if(p.get('aud'))a.value=p.get('aud');f()</script>"""
body=f"""<section class="hero"><div class="w"><h1>The directory for healthcare pros on the road</h1><p>Curated tools and services for <b>travel nurses</b> and <b>medical device sales reps</b>: housing, mileage, gear, CE &amp; licensing, routes, taxes and more.</p><a class="btn" style="cursor:pointer" href="/?aud=nurses#directory">For Travel Nurses</a> <a class="btn" style="cursor:pointer;background:#fff" href="/?aud=reps#directory">For Device Reps</a></div></section><section class="w" id="directory"><h2>Browse by category</h2>{catlinks}<div class="ctl"><input id="q" placeholder="Search tools…" aria-label="Search"><select id="aud" aria-label="Audience"><option value="">All audiences</option><option value="nurses">Travel Nurses</option><option value="reps">Device Sales Reps</option></select><select id="cat" aria-label="Category"><option value="">All categories</option>{opts}</select></div><p id="n"></p><div class="grid">{FEAT}</div><br><div class="grid" id="list">{"".join(card(x) for x in L)}</div></section>{NEWS}{JS}"""
page("index.html",f"{SITE} — Tools for Travel Nurses & Medical Device Reps","Curated directory of housing, mileage tracking, scrubs, CE credits, route planning, staffing, CRM, 1099 taxes and wellness resources for traveling healthcare professionals.",body)
for k,v in CATS.items():
  items=[x for x in L if x["cat"]==k]
  page(f"category/{k}/index.html",f"{v} for Travel Nurses & Device Reps | {SITE}",f"{v}: curated resources for traveling healthcare professionals.",f'<section class="hero"><div class="w"><h1>{v}</h1><p>{len(items)} curated listings for healthcare pros who travel.</p></div></section><section class="w">{catlinks}<div class="grid">{FEAT}{"".join(card(x) for x in items)}</div></section>{NEWS}')
page("sponsor/index.html",f"Sponsor {SITE}","Reach travel nurses and medical device reps with a featured listing and newsletter mention.",f'<section class="hero"><div class="w"><h1>Sponsor {SITE}</h1><p>Put your product in front of traveling healthcare professionals.</p></div></section><section class="w"><p>Pick a package below. Payments are processed securely by Stripe.</p><div class="grid"><div class="card"><h3>Featured category listing</h3><p>Pinned at the top of one category page, labeled "Featured", plus a newsletter mention.</p><p><b>$49 / month</b>. Cancel anytime.</p><p><a class="btn" style="cursor:pointer" href="https://buy.stripe.com/cNi28r1Or4JccjjghZcV200" target="_blank" rel="noopener">Buy Featured Listing</a></p></div><div class="card"><h3>Homepage featured slot</h3><p>Pinned at the top of the homepage directory.</p><p><b>Coming soon</b></p></div><div class="card"><h3>Newsletter mention</h3><p>Sponsor blurb in an issue of the newsletter.</p><p><b>Coming soon</b></p></div></div><p>Questions about sponsoring? Reach out and we will help you pick a package.</p></section>')
urls=["","sponsor/"]+[f"category/{k}/" for k in CATS]
open("dist/sitemap.xml","w").write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+"".join(f"<url><loc>{BASE}/{u}</loc></url>" for u in urls)+"</urlset>")
open("dist/robots.txt","w").write(f"User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n")
print(len(L),"listings",len(CATS),"cats")
